entries[151625] = { ["name"] = "Ruby Qiraji Resonating Crystal", ["text"] = "Binds when picked up\nUnique\nDuration: 7 days\nMount\n(Account-wide)\nUse: Summons and dismisses a rideable Red Qiraji War Tank.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\"Once the Call of the Scarab ends the qiraji will return to their burrows.\"\nSell Price:\n\"The Qiraji War Tank has only been seen recently during the Call of the Scarab, could this hint at a resurfacing of the deadly creatures?\"\nWorld Event:\nCall of the Scarab" }
entries[151626] = { ["name"] = "Sapphire Qiraji Resonating Crystal", ["text"] = "Binds when picked up\nUnique\nDuration: 7 days\nMount\n(Account-wide)\nUse: Summons and dismisses a rideable Blue Qiraji War Tank.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\"Once the Call of the Scarab ends the qiraji will return to their burrows.\"\nSell Price:\n\"The Qiraji War Tank has only been seen recently during the Call of the Scarab, could this hint at a resurfacing of the deadly creatures?\"\nWorld Event:\nCall of the Scarab" }
