entries[151636] = { ["name"] = "Soul of the Archdruid", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 2 Critical Strike\n+ 4 Haste\n+ 3 Mastery\n\nPrismatic Socket\n\nClasses: Druid\nEquip: Gain the Soul of the Forest talent.\n\"The Cenarion Circle reside in the Dreamgrove. They are the guardians of nature, the preservers of balance, and the protectors of all life.\"\nSell Price:" }
entries[151638] = { ["name"] = "Leprous Sack of Pet Supplies", ["text"] = "Binds when picked up\n\"Parts of the bag are falling apart.\"\n<Right Click to Open>" }
entries[151639] = { ["name"] = "Soul of the Slayer", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 3 Critical Strike\n+ 2 Haste\n+ 4 Mastery\n\nPrismatic Socket\n\nClasses: Demon Hunter\nEquip: Gain one of the following talents based on your specialization:\n\nHavoc: First Blood\nVengeance: Fallout\n\"The Illidari reside in the Fel Hammer. They wield the forbidden powers of the demons they slay to fight the forces of chaos - at any cost.\"\nSell Price:" }
entries[151640] = { ["name"] = "Soul of the Deathlord", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 3 Critical Strike\n+ 2 Haste\n+ 4 Mastery\n\nPrismatic Socket\n\nClasses: Death Knight\nEquip: Gain one of the following talents based on your specialization:\n\nBlood: Foul Bulwark\nFrost: Gathering Storm\nUnholy: Bursting Sores\n\"The Knights of the Ebon Blade reside in Acherus, the Ebon Hold. They were once the champions of the scourge. They are now the damned.\"\nSell Price:" }
entries[151641] = { ["name"] = "Soul of the Huntmaster", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 2 Critical Strike\n+ 3 Haste\n+ 4 Mastery\n\nPrismatic Socket\n\nClasses: Hunter\nEquip: Gain one of the following talents based on your specialization:\n\nBeast Mastery: Thrill of the Hunt\nMarksmanship: Lock and Load\nSurvival: Viper's Venom\n\"The Unseen Path reside in the Trueshot Lodge. They are the watchers in the wild. They are the eagle on the wind. They walk the lonely road.\"\nSell Price:" }
entries[151642] = { ["name"] = "Soul of the Archmage", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 4 Critical Strike\n+ 5 Haste\n+ 4 Mastery\n\nPrismatic Socket\n\nClasses: Mage\nEquip: Gain one of the following talents based on your specialization:\n\nArcane: Amplification\nFire: Flame On\nFrost: Frozen Touch\n\"The Tirisgarde reside in the Hall of the Guardian. They are the elite mage-guard of Dalaran, called upon in the past by the Council of Tirisfal to do battle in the absence of the Guardian.\"\nSell Price:" }
entries[151643] = { ["name"] = "Soul of the Grandmaster", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 4 Critical Strike\n+ 4 Haste\n+ 5 Mastery\n\nPrismatic Socket\n\nClasses: Monk\nEquip: Gain one of the following talents based on your specialization:\n\nBrewmaster: High Tolerance\nMistweaver: Mist Wrap\nWindwalker: Eye of the Tiger\n\"The Order of the Broken Temple reside in the Temple of the Five Dawns. They are the bringers of hope to a dim future.\"\nSell Price:" }
entries[151644] = { ["name"] = "Soul of the Highlord", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 3 Critical Strike\n+ 2 Haste\n+ 4 Mastery\n\nPrismatic Socket\n\nClasses: Paladin\nEquip: Gain one of the following talents based on your specialization:\n\nHoly: Divine Purpose\nProtection: Holy Shield\nRetribution: Divine Purpose\n\"The Order of the Silver Hand reside in the Sanctum of Light. They are the united might of the Argent Crusade, the Hand of Argus, the Sunwalkers, and the Blood Knights.\"\nSell Price:" }
entries[151645] = { ["name"] = "Model D1-BB-L3R", ["text"] = "Use: Teaches you how to summon and dismiss Dibbler.\nRight Click to summon and dismiss Dibbler.\nRequires level 1 to 80 ( 80)" }
entries[151646] = { ["name"] = "Soul of the High Priest", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 3 Critical Strike\n+ 4 Haste\n+ 2 Mastery\n\nPrismatic Socket\n\nClasses: Priest\nEquip: Gain one of the following talents based on your specialization:\n\nDiscipline: Twist of Fate\nHoly: Surge of Light\nShadow: Twist of Fate\n\"The Conclave reside in the Netherlight Temple. They are the masters of the Light and embracers of the Void - for light cannot exist without darkness, and darkness without light.\"\nSell Price:" }
entries[151647] = { ["name"] = "Soul of the Farseer", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 4 Critical Strike\n+ 3 Haste\n+ 5 Mastery\n\nPrismatic Socket\n\nClasses: Shaman\nEquip: Gain one of the following talents based on your specialization:\n\nElemental: Echo of the Elements\nEnhancement: Landslide\nRestoration: Echo of the Elements\n\"The Earthen Ring reside in the Heart of Azeroth. They wield the power of the elemental forces between which they maintain balance. They are the true masters of the elements.\"\nSell Price:" }
entries[151648] = { ["name"] = "Engorged Raptor Parts", ["text"] = "Quest Item\n\"Tortollans must have strong stomachs if Kajosh is willing to eat raw raptor meat.\"" }
entries[151649] = { ["name"] = "Soul of the Netherlord", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 2 Critical Strike\n+ 4 Haste\n+ 3 Mastery\n\nPrismatic Socket\n\nClasses: Warlock\nEquip: Gain one of the following talents based on your specialization:\n\nAffliction: Soul Conduit\nDemonology: Soul Conduit\nDestruction: Eradication\n\"The Council of the Black Harvest reside in the Dreadscar Rift. They are the takers of souls, the commanders of demons, and the masters of the dark arts.\"\nSell Price:" }
entries[151650] = { ["name"] = "Soul of the Battlelord", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 2 Critical Strike\n+ 3 Haste\n+ 4 Mastery\n\nPrismatic Socket\n\nClasses: Warrior\nEquip: Gain one of the following talents based on your specialization:\n\nArms: Anger Management\nFury: Massacre\nProtection: Vengeance\n\"The Valarjar reside in the Skyhold. They are the mighty ascended champions of Odyn who protect the world from all threats.\"\nSell Price:" }
entries[151651] = { ["name"] = "Gravitational Reduction Slippers", ["text"] = "Use: Affix the Gravitational Reduction Slippers to your current footwear allowing you to jump higher. Lasts 3 min.\n\nOnly usable outdoors in Broken Isles and on Argus. (15 Min Cooldown)" }
entries[151652] = { ["name"] = "Wormhole Generator: Argus", ["text"] = "Binds when used\nToy\nUse: Teleports the player to a random location on Argus. (15 Min Cooldown)\nRequires Legion Engineering (1)\n\"The user is responsible for final destinations teleported to, and may not take any legal action against the maker of this device.\"\nSell Price:" }
entries[151653] = { ["name"] = "Broken Isles Recipe Scrap", ["text"] = "Binds when picked up\nUnique (10)\nUse: Combine 10 Broken Isles Recipe Scraps to assemble a cooking recipe you've not yet discovered." }
entries[151654] = { ["name"] = "Vantus Rune Technique: Antorus, the Burning Throne", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Vantus Rune: Antorus, the Burning Throne.\nCraft a Vantus Rune: Antorus, The Burning Throne\nRequires Legion Inscription (1)\nSell Price:\nVantus Rune: Antorus, the Burning Throne\nUse: Attune yourself to the energies of the targeted Antorus, the Burning Throne raid boss, increasing your Versatility by 3380 when fighting that boss. This effect lasts for an entire week.\n\nYou can only use one Vantus Rune per week.\nSell Price:\nRequires Sallow Pigment (10), Roseate Pigment (30)" }
entries[151655] = { ["name"] = "Vantus Rune Technique: Antorus, The Burning Throne", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Vantus Rune: Antorus, The Burning Throne more efficiently.\nReduces the materials required to craft a Vantus Rune: Antorus, The Burning Throne.\nRequires Legion Inscription (1)\nSell Price:\nVantus Rune: Antorus, the Burning Throne\nUse: Attune yourself to the energies of the targeted Antorus, the Burning Throne raid boss, increasing your Versatility by 3380 when fighting that boss. This effect lasts for an entire week.\n\nYou can only use one Vantus Rune per week.\nSell Price:\nRequires Sallow Pigment (8), Roseate Pigment (30)" }
entries[151656] = { ["name"] = "Vantus Rune Technique: Antorus, the Burning Throne", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Vantus Rune: Antorus, the Burning Throne more efficiently.\nGreatly reduces the materials required to craft a Vantus Rune: Antorus, The Burning Throne.\nRequires Legion Inscription (1)\nSell Price:\nVantus Rune: Antorus, the Burning Throne\nUse: Attune yourself to the energies of the targeted Antorus, the Burning Throne raid boss, increasing your Versatility by 3380 when fighting that boss. This effect lasts for an entire week.\n\nYou can only use one Vantus Rune per week.\nSell Price:\nRequires Sallow Pigment (6), Roseate Pigment (30)" }
entries[151657] = { ["name"] = "Recipe: Lightblood Elixir", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Teaches you how to make a Lightblood Elixir.\nCreate a Lightblood Elixir.\nRequires Legion Alchemy (1)\nSell Price:\nLightblood Elixir\nUse: Infuses the player with Light energy allowing them to sometimes deal extra damage against demons. Lasts 30 min.\n\nOnly usable outdoors on Broken Isles and Argus. (3 Sec Cooldown)\nSell Price:\nRequires Astral Glory (25), Primal Sargerite , Crystal Vial" }
entries[151658] = { ["name"] = "Recipe: Lightblood Elixir", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Teaches you how to make a Lightblood Elixir more efficiently.\nCreate a Lightblood Elixir more efficiently.\nRequires Legion Alchemy (1)\nSell Price:\nLightblood Elixir\nUse: Infuses the player with Light energy allowing them to sometimes deal extra damage against demons. Lasts 30 min.\n\nOnly usable outdoors on Broken Isles and Argus. (3 Sec Cooldown)\nSell Price:\nRequires Astral Glory (20), Crystal Vial" }
entries[151659] = { ["name"] = "Recipe: Lightblood Elixir", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to make a Lightblood Elixir even more efficiently, with a chance to create multiple potions.\nChance to create multiple potions.\nRequires Legion Alchemy (1)\nSell Price:\nLightblood Elixir\nUse: Infuses the player with Light energy allowing them to sometimes deal extra damage against demons. Lasts 30 min.\n\nOnly usable outdoors on Broken Isles and Argus. (3 Sec Cooldown)\nSell Price:\nRequires Astral Glory (15), Crystal Vial" }
