entries[151706] = { ["name"] = "Recipe: Astral Alchemist Stone", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Teaches you how to make an Astral Alchemist Stone.\nCraft an Astral Alchemist Stone.\nRequires Legion Alchemy (1)\nSell Price:\nAstral Alchemist Stone\nBinds when equipped\nUnique-Equipped\nTrinket\n+ 7 Versatility\nEquip: When you heal or deal damage you have a chance to increase your Strength, Agility, or Intellect by 19 for 15 sec. Your highest stat is always chosen.\nEquip: Increases the effect that healing and mana potions have on the wearer by 40%. This effect does not stack.\nRequires Legion Alchemy (1)\n\"Can be used for transmutations in place of a Philosopher's Stone.\"\nSell Price:\nRequires Astral Glory (75), Infernal Alchemist Stone , Primal Sargerite (5)" }
entries[151707] = { ["name"] = "Recipe: Astral Alchemist Stone", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Teaches you how to more efficiently make an Astral Alchemist Stone.\nCraft an Astral Alchemist Stone more efficiently.\nRequires Legion Alchemy (1)\nRequires Argussian Reach\n- Revered\nSell Price:\nAstral Alchemist Stone\nBinds when equipped\nUnique-Equipped\nTrinket\n+ 7 Versatility\nEquip: When you heal or deal damage you have a chance to increase your Strength, Agility, or Intellect by 19 for 15 sec. Your highest stat is always chosen.\nEquip: Increases the effect that healing and mana potions have on the wearer by 40%. This effect does not stack.\nRequires Legion Alchemy (1)\n\"Can be used for transmutations in place of a Philosopher's Stone.\"\nSell Price:\nRequires Astral Glory (60), Infernal Alchemist Stone , Primal Sargerite (4)" }
entries[151708] = { ["name"] = "Recipe: Astral Alchemist Stone", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to even more efficiently make an Astral Alchemist Stone.\nCraft an Astral Alchemist Stone even more efficiently.\nRequires Legion Alchemy (1)\nRequires Argussian Reach\n- Exalted\nSell Price:\nAstral Alchemist Stone\nBinds when equipped\nUnique-Equipped\nTrinket\n+ 7 Versatility\nEquip: When you heal or deal damage you have a chance to increase your Strength, Agility, or Intellect by 19 for 15 sec. Your highest stat is always chosen.\nEquip: Increases the effect that healing and mana potions have on the wearer by 40%. This effect does not stack.\nRequires Legion Alchemy (1)\n\"Can be used for transmutations in place of a Philosopher's Stone.\"\nSell Price:\nRequires Astral Glory (50), Infernal Alchemist Stone , Primal Sargerite (3)" }
entries[151709] = { ["name"] = "Plans: Felslate Anchor", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make a Felslate Anchor.\nCraft a Felslate Anchor.\nRequires Legion Blacksmithing (1)\n\nFelslate Anchor\nUse: Attach an anchor to your legs which sends you plummeting towards the ocean floor. Only usable in water. (30 Sec Cooldown)\n\"Jam-packed with enough weight to send a kraken to the ocean floor!\"\nRequires Felslate (50)" }
entries[151710] = { ["name"] = "Recipe: Transmute Primal Sargerite", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to transmute Blood of Sargeras to Primal Sargerite.\nTransmute Blood of Sargeras into Primal Sargerite.\nRequires Legion Alchemy (1)\nSell Price:\nPrimal Sargerite\nBinds when picked up\nCrafting Reagent\n\"Used in the crafting of tradeskill items or can be turned in to Trader Caelen at the Obliterum Forge in Dalaran.\"\nSell Price:\nRequires Blood of Sargeras (25)" }
entries[151711] = { ["name"] = "Plans: Empyrial Breastplate", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Teaches you how to make an Empyrial Breastplate.\nCraft an Empyrial Breastplate.\nRequires Legion Blacksmithing (1)\nSell Price:\nEmpyrial Breastplate\nBinds when equipped\nChest Plate\n18 Armor\n+5 [Strength or Intellect]\n+7 Stamina\nDurability 165 / 165\nSell Price:\nRequires Empyrium (125), Primal Sargerite (10)" }
entries[151712] = { ["name"] = "Plans: Empyrial Breastplate", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Teaches you how to more efficiently make an Empyrial Breastplate.\nReduces the materials required to craft an Empyrial Breastplate.\nRequires Legion Blacksmithing (1)\nRequires Army of the Light\n- Revered\nSell Price:\nEmpyrial Breastplate\nBinds when equipped\nChest Plate\n18 Armor\n+5 [Strength or Intellect]\n+7 Stamina\nDurability 165 / 165\nSell Price:\nRequires Empyrium (110), Primal Sargerite (7)" }
entries[151713] = { ["name"] = "Plans: Empyrial Breastplate", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to even more efficiently make an Empyrial Breastplate.\nGreatly reduces the materials required to craft an Empyrial Breastplate.\nRequires Legion Blacksmithing (1)\nSell Price:\nEmpyrial Breastplate\nBinds when equipped\nChest Plate\n18 Armor\n+5 [Strength or Intellect]\n+7 Stamina\nDurability 165 / 165\nSell Price:\nRequires Empyrium (95), Primal Sargerite (5)" }
entries[151714] = { ["name"] = "Schematic: Gravitational Reduction Slippers", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make Gravitational Reduction Slippers.\nCraft Gravitational Reduction Slippers.\nRequires Legion Engineering (1)\nSell Price:\nGravitational Reduction Slippers\nUse: Affix the Gravitational Reduction Slippers to your current footwear allowing you to jump higher. Lasts 3 min.\n\nOnly usable outdoors in Broken Isles and on Argus. (15 Min Cooldown)\nRequires Empyrium (25), Oversized Blasting Cap (8), Primal Sargerite" }
entries[151717] = { ["name"] = "Schematic: Wormhole Generator: Argus", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make a Wormhole Generator: Argus.\nCraft a Wormhole Generator: Argus.\nRequires Legion Engineering (1)\nSell Price:\nWormhole Generator: Argus\nBinds when used\nToy\nUse: Teleports the player to a random location on Argus. (15 Min Cooldown)\nRequires Legion Engineering (1)\n\"The user is responsible for final destinations teleported to, and may not take any legal action against the maker of this device.\"\nSell Price:\nRequires Empyrium (30), Loose Trigger (2), Primal Sargerite (2)" }
