entries[151782] = { ["name"] = "The Topless Tower", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nHead Plate\n13 Armor\n+5 [Strength or Intellect]\n+7 Stamina\n+ 5 Critical Strike\n+ 5 Mastery\nDurability 120 / 120\nClasses: Paladin\nEquip: Light of Dawn has a 10% chance to grant you Avenging Wrath for 8 sec.\n\"In the room the men have come and gone, / Talking of Alleria and Turalyon.\"\nSell Price:" }
entries[151783] = { ["name"] = "Chameleon Song", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nHead Leather\n6 Armor\n+5 [Agility or Intellect]\n+7 Stamina\n+ 5 Haste\n+ 5 Mastery\nDurability 120 / 120\nClasses: Druid\nEquip: Wild Growth has a 15% chance to grant you Incarnation: Tree of Life for 12 sec.\n\"The Keepers maintained peace with the knowledge that nothing endures: not a tree, not love, not even a death by violence.\"\nSell Price:" }
entries[151784] = { ["name"] = "Doorway to Nowhere", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nBack\n3 Armor\n+3 [Agility or Intellect]\n+4 Stamina\n+ 3 Haste\n+ 3 Mastery\nClasses: Monk\nEquip: Essence Font has a 20% chance to summon Chi-Ji for until canceled.\n\"Two paths diverged in the mist, and I... / I took the third, untraveled by.\"\nSell Price:" }
entries[151785] = { ["name"] = "Fire in the Deep", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nChest Mail\n12 Armor\n+5 [Agility or Intellect]\n+7 Stamina\n+ 5 Critical Strike\n+ 5 Mastery\nDurability 200 / 200\nClasses: Shaman\nEquip: Healing Rain has a 15% chance to grant you Ascendance for 6 sec.\n\"And the wrath of the demons would challenge their worth; / And the idols were broke in the shrine of the Earth.\"\nSell Price:" }
entries[151786] = { ["name"] = "Inner Hallation", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nShoulder Cloth\n3 Armor\n+4 Intellect\n+6 Stamina\n+ 4 Haste\n+ 3 Mastery\nDurability 120 / 120\nClasses: Priest\nEquip: Power Word: Radiance has a 35% chance to grant you Power Infusion for 9 sec.\n\"Lend me your power, and immortality will be ours.\"\nSell Price:" }
entries[151787] = { ["name"] = "The Alabaster Lady", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nHead Cloth\n4 Armor\n+5 Intellect\n+7 Stamina\n+ 5 Critical Strike\n+ 5 Mastery\nDurability 120 / 120\nClasses: Priest\nEquip: Prayer of Mending has a 15% chance to grant you Apotheosis for 8 sec.\n\"When the stars threw down their spears / And water'd heaven with their tears: / Did she smile her work to see?\"\nSell Price:" }
entries[151788] = { ["name"] = "Stormstout's Last Gasp", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nShoulder Leather\n6 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 3 Haste\n+ 4 Versatility\nDurability 120 / 120\nClasses: Monk\nEquip: Keg Smash gains 1 additional charge and deals 25% increased damage.\n\"Why do we fight? To protect home and family... To preserve balance and bring harmony.\"\nSell Price:" }
entries[151789] = { ["name"] = "Defense Construct Identifier", ["text"] = "Binds when picked up\n\"Marks the bearer as one exempt from Annihilation Protocols.\"\nSell Price:" }
entries[151790] = { ["name"] = "Red Winter Clothes", ["text"] = "Cosmetic\nBinds when equipped\nChest Cosmetic\nUse: Add this appearance to your Warband collection.\n\nWinter Garb (0/3)\nGreen Winter Clothes\nGreen Winter Hat\nRed Winter Clothes\nRed Winter Hat\nWinter Boots\n(3) Set : Full Winter Garb\nSell Price:" }
entries[151791] = { ["name"] = "Winter Boots", ["text"] = "Cosmetic\nBinds when equipped\nFeet Cosmetic\nUse: Add this appearance to your Warband collection.\n\nWinter Garb (0/3)\nGreen Winter Clothes\nGreen Winter Hat\nRed Winter Clothes\nRed Winter Hat\nWinter Boots\n(3) Set : Full Winter Garb\nSell Price:" }
entries[151792] = { ["name"] = "Green Winter Clothes", ["text"] = "Cosmetic\nBinds when equipped\nChest Cosmetic\nUse: Add this appearance to your Warband collection.\n\nWinter Garb (0/3)\nGreen Winter Clothes\nGreen Winter Hat\nRed Winter Clothes\nRed Winter Hat\nWinter Boots\n(3) Set : Full Winter Garb\nSell Price:" }
entries[151793] = { ["name"] = "Pig Fetish", ["text"] = "Quest Item\nUnique\n\"Exudes a dark, greasy magic and smells like burned bacon.\"" }
entries[151795] = { ["name"] = "Soulflayer's Corruption", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nChest Plate\n18 Armor\n+5 Strength\n+7 Stamina\n+ 5 Critical Strike\n+ 5 Mastery\nDurability 200 / 200\nClasses: Death Knight\nEquip: Blood Plague gains 100% increased damage and healing.\n\"The origins of the Soulflayer remain unknown. There are no mentions of him in any of the Titan records.\"\nSell Price:" }
entries[151796] = { ["name"] = "Cold Heart", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nChest Plate\n18 Armor\n+5 Strength\n+7 Stamina\n+ 5 Critical Strike\n+ 5 Mastery\nDurability 200 / 200\nClasses: Death Knight\nEquip: Every 2 sec, gain a stack of Cold Heart, causing your next Chains of Ice to deal (21% of Attack Power) Shadowfrost damage. Stacks up to 20 times.\n\nIf Chains of Ice is used when you have 20 stacks of Cold Heart, the target will also be stunned in a block of ice for 4 sec.\n\"The beating of a frozen heart can be heard from a vast distance away, reminding all living things of their inevitable death.\"\nSell Price:" }
entries[151797] = { ["name"] = "Death Screamers", ["text"] = "Binds when picked up\nThis Item Begins a Quest\nHands\n+35,548 Strength\n+81,730 Stamina\n+ 4,531 Haste\n+ 3,927 Mastery\nClasses: Death Knight\n\"The screams of the dead resonate through, always waiting to silence the next victim.\"\n<Right Click to Read>\nSell Price:" }
entries[151798] = { ["name"] = "Chaos Theory", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nBack\n3 Armor\n+3 Agility\n+4 Stamina\n+ 3 Critical Strike\n+ 3 Haste\nClasses: Demon Hunter\nEquip: Blade Dance has a 10% chance to grant you Chaos Blades for 6 sec. (500ms cooldown)\n\"Within chaos there exists repetition, feedback loops, and underlying patterns.\"\nSell Price:" }
entries[151799] = { ["name"] = "Oblivion's Embrace", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nLegs Leather\n7 Armor\n+5 Agility\n+7 Stamina\n+ 5 Versatility\n+ 5 Mastery\nDurability 145 / 145\nClasses: Demon Hunter\nEquip: Demon Spikes gains 1 additional charge.\n\"There is no better guide to the world than oblivion.\"\nSell Price:" }
entries[151800] = { ["name"] = "Radiant Moonlight", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nBack\n3 Armor\n+3 [Agility or Intellect]\n+4 Stamina\n+ 3 Haste\n+ 3 Mastery\nClasses: Druid\nEquip: Full Moon becomes Full Moon once more before resetting to New Moon.\n\"Doubt thou the stars are fire;Doubt that the sun doth move.\"\nSell Price:" }
entries[151801] = { ["name"] = "Behemoth Headdress", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nHead Leather\n6 Armor\n+5 [Agility or Intellect]\n+7 Stamina\n+ 5 Critical Strike\n+ 5 Mastery\nDurability 120 / 120\nClasses: Druid\nEquip: Finishing moves extend the duration of Tiger's Fury by 0.5 sec per combo point spent. (100ms cooldown)\n\"Don't wake a tiger from its nap.\"\nSell Price:" }
entries[151802] = { ["name"] = "Fury of Nature", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nBack\n3 Armor\n+3 [Agility or Intellect]\n+4 Stamina\n+ 3 Critical Strike\n+ 3 Mastery\nClasses: Druid\nEquip: While in Bear From, you deal 30% increased Nature and Arcane damage, and are healed for 30% of all Nature and Arcane damage done.\n\"Harmony between the natural and supernatural forces may be difficult to achieve, but leads to substantial greatness.\"\nSell Price:" }
entries[151803] = { ["name"] = "Celerity of the Windrunners", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nBack\n3 Armor\n+3 Agility\n+4 Stamina\n+ 3 Haste\n+ 3 Mastery\nClasses: Hunter\nEquip: Increases your Haste by 3%.\nEquip: Windburst grants you 15% Haste for 6 sec.\n\"'Your heart flew straight as any arrow upon the wind, sister. You were the brightest of our Order. You were the most beloved of our kin.' -Sylvanas, to Alleria.\"\nSell Price:" }
entries[151804] = { ["name"] = "Black Tuxedo Pants", ["text"] = "Cosmetic\nBinds to Warband\nLegs Cosmetic\nUse: Add this appearance to your Warband collection.\n\nSpring Tuxedo (0/2)\nBlack Tuxedo Pants\nWhite Tuxedo Shirt\n(2) Set : Spring Tuxedo\nSell Price:" }
entries[151805] = { ["name"] = "Parsel's Tongue", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nChest Mail\n12 Armor\n+5 Agility\n+7 Stamina\n+ 5 Haste\n+ 5 Mastery\nDurability 200 / 200\nClasses: Hunter\nEquip: Cobra Shot increases the damage done by you and your pets by 1% and your leech by 2% for 8 sec, stacking up to 4 times. (500ms cooldown)\n\"A rare power usually belonging to those with an affinity for serpents.\"\nSell Price:" }
entries[151806] = { ["name"] = "Elegant Dress", ["text"] = "Cosmetic\nBinds to Warband\nChest Cosmetic\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[151807] = { ["name"] = "Unseen Predator's Cloak", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nBack\n3 Armor\n+3 Agility\n+4 Stamina\n+ 3 Haste\n+ 3 Mastery\nClasses: Hunter\nEquip: Increases all damage done by 3%.\nEquip: Gain 10% increased critical strike chance against enemies burning from your Explosive Trap.\n\"Even the most powerful enemy has a weakness that can be exposed.\"\nSell Price:" }
entries[151808] = { ["name"] = "Mantle of the First Kirin Tor", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nShoulder Cloth\n3 Armor\n+4 Intellect\n+6 Stamina\n+ 4 Critical Strike\n+ 3 Haste\nDurability 120 / 120\nClasses: Mage\nEquip: Arcane Barrage has a 10% chance per Arcane Charge consumed to launch an Arcane Orb in front of you.\n\"Thousands of years ago, the high elves of Quel'Thalas taught the arcane arts to the humans, who went on to form the Kirin Tor and rule over Dalaran.\"\nSell Price:" }
entries[151809] = { ["name"] = "Contained Infernal Core", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nShoulder Cloth\n3 Armor\n+4 Intellect\n+6 Stamina\n+ 4 Critical Strike\n+ 3 Haste\nDurability 120 / 120\nClasses: Mage\nEquip: Casting 30 Fireballs or Pyroblasts calls down a Meteor at your target.\n\"The Infernal Core frequently erupts with jets of flame that burn with enough heat to melt through the toughest of materials.\"\nSell Price:" }
entries[151810] = { ["name"] = "Shattered Fragments of Sindragosa", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nHead Cloth\n4 Armor\n+5 Intellect\n+7 Stamina\n+ 5 Critical Strike\n+ 5 Haste\nDurability 120 / 120\nClasses: Mage\nEquip: Casting 15 Frostbolts or Flurries calls down a Comet Storm at your target.\n\"Forged from the remnants of Arthas' destruction at Sindragosa's Fall, this sends a chill down the wearer's spine.\"\nSell Price:" }
entries[151811] = { ["name"] = "The Wind Blows", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nHead Leather\n6 Armor\n+5 [Agility or Intellect]\n+7 Stamina\n+ 5 Critical Strike\n+ 5 Mastery\nDurability 120 / 120\nClasses: Monk\nEquip: Increases your damage done by 3%.\nEquip: Strike of the Windlord has 20% reduced cooldown and makes your next Blackout Kick cost no Chi. (1s cooldown)\n\"The sun rises, the wind blows, and the mighty fall.\"\nSell Price:" }
entries[151812] = { ["name"] = "Pillars of Inmost Light", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nShoulder Plate\n12 Armor\n+4 [Strength or Intellect]\n+6 Stamina\n+ 4 Critical Strike\n+ 3 Haste\nDurability 120 / 120\nClasses: Paladin\nEquip: Ardent Defender has 25% reduced cooldown.\nEquip: Eye of Tyr deals 300% increased damage and has 25% reduced cooldown.\n\"The light shines brightest in those it consumes.\"\nSell Price:" }
entries[151813] = { ["name"] = "Scarlet Inquisitor's Expurgation", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nChest Plate\n18 Armor\n+5 [Strength or Intellect]\n+7 Stamina\n+ 5 Haste\n+ 5 Mastery\nDurability 200 / 200\nClasses: Paladin\nEquip: Every 2 sec, gain 6% increased damage to your next Divine Storm, stacking up to 30 times.\n\"Can you not see it, brothers and sisters? There is but one way to wipe the Scourge from the face of Azeroth.\"\nSell Price:" }
entries[151814] = { ["name"] = "Heart of the Void", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nChest Cloth\n5 Armor\n+5 Intellect\n+7 Stamina\n+ 5 Critical Strike\n+ 5 Haste\nDurability 200 / 200\nClasses: Priest\nEquip: Void Eruption deals 75% increased damage and heals you for 25% of the damage done.\n\"The Void is not empty. It is full of malice, despair, and death.\"\nSell Price:" }
entries[151815] = { ["name"] = "The Empty Crown", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nHead Leather\n6 Armor\n+5 Agility\n+7 Stamina\n+ 5 Critical Strike\n+ 5 Mastery\nDurability 120 / 120\nClasses: Rogue\nEquip: Increases Energy regeneration by 1 per sec. (500ms cooldown)\nEquip: Kingsbane generates 40 Energy over 5 sec. (500ms cooldown)\n\"It's hard to put a leash on a dog once you've put a crown on its head.\"\nSell Price:" }
entries[151816] = { ["name"] = "Horde Banner", ["text"] = "Quest Item\nUnique\nUse: Plant a Horde Banner in a nearby Zanchuli traitor's corpse." }
entries[151817] = { ["name"] = "The Curse of Restlessness", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nBack\n3 Armor\n+3 Agility\n+4 Stamina\n+ 3 Critical Strike\n+ 3 Mastery\nClasses: Rogue\nEquip: Restless Blades reduces the cooldown of Adrenaline Rush by an additional 0.5 sec per combo point spent.\nEquip: Restless Blades reduces the cooldown of Curse of the Dreadblades by 0.25 sec per combo point spent.\n\"We get restless easily. We need something to do.\"\nSell Price:" }
entries[151818] = { ["name"] = "The First of the Dead", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nHands Leather\n5 Armor\n+4 Agility\n+6 Stamina\n+ 3 Critical Strike\n+ 4 Mastery\nDurability 70 / 70\nClasses: Rogue\nEquip: For 2 sec after activating Symbols of Death, Shadowstrike generates 3 additional combo points and Backstab generates 4 additional combo points. (500ms cooldown)\n\"Death comes to us all in the end...\"\nSell Price:" }
entries[151819] = { ["name"] = "Smoldering Heart", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nHands Mail\n7 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 4 Haste\n+ 3 Mastery\nDurability 70 / 70\nClasses: Shaman\nEquip: You have a [ Stormstrike : 0.12% / 0.10%] chance per Maelstrom spent to gain Ascendance for 10 sec.\n\"The essence of thousands of fiery elementals have been imbued in these gloves, yet they are strangely cool to the touch.\"\nSell Price:" }
entries[151820] = { ["name"] = "Primal Ascendant's Stormcallers", ["text"] = "Binds when picked up\nThis Item Begins a Quest\nShoulder\n+35,548 [Agility or Intellect]\n+81,730 Stamina\n+ 3,927 Haste\n+ 4,531 Mastery\nClasses: Shaman\n\"There is a raw power emitting from these that suggest a massive surge of lighting was a key ingredient in the creation of these pauldrons.\"\n<Right Click to Read>\nSell Price:" }
entries[151821] = { ["name"] = "The Master Harvester", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nChest Cloth\n5 Armor\n+5 Intellect\n+7 Stamina\n+ 5 Haste\n+ 5 Mastery\nDurability 200 / 200\nClasses: Warlock\nEquip: Demonology\nEach Soul Shard you spend has a 3% chance to grant you Soul Harvest for 8 sec.\n\nDestruction\nEach Soul Shard you spend has a 6% chance to grant you Soul Harvest for 8 sec.\n\nAffliction\nEach Soul Shard you spend has a 9% chance to grant you Soul Harvest for 8 sec.\n\"Out of suffering emerges the strongest of souls.\"\nSell Price:" }
entries[151822] = { ["name"] = "Ararat's Bloodmirror", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nLegs Plate\n16 Armor\n+5 Strength\n+7 Stamina\n+ 5 Versatility\n+ 5 Mastery\nDurability 145 / 145\nClasses: Warrior\nEquip: Shield Block and Spell Reflection gain 1 additional charge.\n\"His blood infuses the glimmering steel, spilled by dragons, gods, and demons. Even from beyond, he protects his friends.\"\nSell Price:" }
entries[151823] = { ["name"] = "The Great Storm's Eye", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nHead Plate\n13 Armor\n+5 Strength\n+7 Stamina\n+ 5 Haste\n+ 5 Mastery\nDurability 120 / 120\nClasses: Warrior\nEquip: Bladestorm increases your movement speed by 10% and your damage done by 2% for 6 sec, increasing periodically and stacking up to 6 times.\n\"In the eye of the tornado, there's no high and low, no floor and sky.\"\nSell Price:" }
entries[151824] = { ["name"] = "Valarjar Berserkers", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nLegs Plate\n16 Armor\n+5 Strength\n+7 Stamina\n+ 4 Critical Strike\n+ 6 Haste\nDurability 145 / 145\nClasses: Warrior\nEquip: Rampage critical strikes against the primary target generate 6 Rage.\n\"They aren't known for their subtlety.\"\nSell Price:" }
entries[151825] = { ["name"] = "Horn of Hatuun", ["text"] = "Quest Item\nUnique\nUse: Calls forth Krokul Ridgestalkers from the shadows to aid you in battle. (30 Sec Cooldown)\n\"Let the call of battle ring out. We strike as one!\"" }
entries[151826] = { ["name"] = "Spirit Mask", ["text"] = "Quest Item\nUse: Use the spirit mask to transition into the realm of spirits." }
entries[151828] = { ["name"] = "Ageless Bronze Drake", ["text"] = "Binds when picked up\nUse: Teaches you how to summon and dismiss this companion.\nRight Click to summon and dismiss your proto-whelp.\nRequires level 1 to 80 ( 80)\nAvailable with the release of Legion Remix: Legionfall.\nSell Price:" }
entries[151829] = { ["name"] = "Bronze Proto-Whelp", ["text"] = "Binds when picked up\nUse: Teaches you how to summon and dismiss this companion.\nRight Click to summon and dismiss your proto-whelp.\nRequires level 1 to 80 ( 80)\nAvailable with the release of Legion Remix: Legionfall.\nSell Price:" }
entries[151830] = { ["name"] = "Light's Judgment", ["text"] = "Use: Calls upon the Vindicaar to release a beam of Holy Light to blast your enemies, inflicting 100 Holy damage to enemies within 15 yards and stunning them for 5 sec.\n\nCan only be used on Argus. (2 Min Cooldown)" }
entries[151837] = { ["name"] = "Invocation Array", ["text"] = "Quest Item\n\"These long, slender crystals are coveted for their use in focusing the Light into wrathful blasts.\"" }
entries[151838] = { ["name"] = "Judgment Core", ["text"] = "Quest Item\n\"It is said that the Judgment Core is the crowning achievement of the Army of the Light's artificers.\"" }
entries[151839] = { ["name"] = "Vindicator Plating", ["text"] = "Quest Item\n\"The Grand Army's lightforged armor is honed to protect their vindicators from the Legion's fel magic.\"" }
entries[151842] = { ["name"] = "Krokul Armor Set", ["text"] = "Binds when picked up\nUse: Set a Champion's power level to 900.\nSell Price:" }
entries[151843] = { ["name"] = "Eredath Armor Set", ["text"] = "Binds when picked up\nUse: Set a Champion's power level to 925.\nSell Price:" }
entries[151844] = { ["name"] = "Xenedar Armor Set", ["text"] = "Binds when picked up\nUse: Set a Champion's power level to 950.\nSell Price:" }
entries[151845] = { ["name"] = "Used Vial", ["text"] = "Quest Item\n\"There appear to be traces of some sort of golden fluid in it.\"" }
entries[151848] = { ["name"] = "Iron Ore", ["text"] = "Warfronts Prototype Main" }
entries[151849] = { ["name"] = "Scroll of Inferno", ["text"] = "Quest Item\nUnique\nUse: Read a magic scroll to destroy nearby profane totems. (5 Sec Cooldown)" }
entries[151851] = { ["name"] = "Immaculate Felcore", ["text"] = "Quest Item\n\"The heart of a pure fel entity, brimming with chaotic energy.\"" }
entries[151852] = { ["name"] = "Edicts of Gral", ["text"] = "Quest Item\n\"The text on this scroll is of an ancient troll dialect and written using a special code. It could take a lifetime to unravel its complexity.\"" }
entries[151853] = { ["name"] = "Waves of Power", ["text"] = "Quest Item\n\"Ancient spell work emblazons this scroll in a collection of symbols that are beyond your understanding.\"" }
entries[151854] = { ["name"] = "Scroll of Purify", ["text"] = "Quest Item\n\"Only the spell's title is legible on this ancient scroll.\"" }
entries[151855] = { ["name"] = "Artifact of Gral", ["text"] = "Quest Item\n\"To the untrained eye this relic appears as nothing more than a decorative piece of ruin.\"" }
entries[151856] = { ["name"] = "Withered Astral Glory", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"An unusable version of the herb.\"" }
entries[151857] = { ["name"] = "Adolescent Astral Glory", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"An astral glory sapling.\"" }
entries[151858] = { ["name"] = "Astral Glory Root Cluster", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"A small, coccoon-like root ball with hints of energy eminating from the interior.\"" }
entries[151859] = { ["name"] = "Scroll of Illusion", ["text"] = "Quest Item\nUse: Mask an Antiquity of Gral.\n\"The spells on this page are very specific, and have been dumbed down for even the most simple of minds to use.\"" }
entries[151860] = { ["name"] = "Empyrium Deposit Chunk", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"The ore seems to have a starry effect to its surface.\"" }
entries[151861] = { ["name"] = "Empyrium Dust", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"Small remnants of empyrium ore.\"" }
entries[151862] = { ["name"] = "Unusable Empyrium Core", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"A fractured core of empyrium ore.\"" }
entries[151863] = { ["name"] = "Empyrium Seam Chunk", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"The ore seems to have a starry effect to its surface.\"" }
entries[151864] = { ["name"] = "Embedded Empyrium Ore", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"A chunk of empyrium ore with large portions of unusable rock.\"" }
entries[151865] = { ["name"] = "Empyrium Bits", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"Small bits and pieces of empyrium ore.\"" }
entries[151866] = { ["name"] = "Tainted Scraps", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"These scraps of fiendish leather appear tainted and emit a very foul smell.\"" }
entries[151867] = { ["name"] = "Spoiled Fiendish Leather", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"The corruption emitting from the beast was able to spoil this piece of leather.\"" }
entries[151868] = { ["name"] = "Corrupted Tooth", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"The corruption from the beast has spread into this tooth, rendering it useless.\"" }
entries[151870] = { ["name"] = "Scroll of Grall", ["text"] = "Binds when picked up\nUse: Take the form of a shark." }
entries[151871] = { ["name"] = "Crate of Felslate", ["text"] = "Quest Item\n\"A large crate of felslate ore.\"" }
entries[151872] = { ["name"] = "Empyrial Breastplate", ["text"] = "Quest Item\n\"A shimmering piece of gold and white armor.\"" }
entries[151874] = { ["name"] = "Lightweave Loom", ["text"] = "Quest Item\n\"A dectorative loom with golden etching engraved into it.\"" }
entries[151875] = { ["name"] = "Call to the Light", ["text"] = "Binds when picked up\nUse: Summons a Champion of the Light to fight by your side for 12 sec." }
entries[151876] = { ["name"] = "Vorel's Design Book", ["text"] = "Quest Item\n\"A large tome filled with different jewelcrafting designs.\"" }
entries[151877] = { ["name"] = "Barrel of Eyepatches", ["text"] = "Binds when picked up\nToy\nClasses: Rogue\nUse: Summon a barrel containing mystery eyepatches for you and all your friends. You'll Barrel-y Believe The Results! (1 Hour Cooldown)\n\"So Much Fun, You'll Y'aardly Know What To Do With Yourself\"" }
entries[151878] = { ["name"] = "Empyrial Crown", ["text"] = "Quest Item\n\"The crown sparkles like the stars, with each jewel placed just so.\"" }
