entries[151955] = { ["name"] = "Acrid Catalyst Injector", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+5 Intellect\nEquip: Your damaging spells that critically strike have a chance to increase your Haste, Mastery, or Critical Strike by 1 for 45 sec, stacking up to 5 times. When any stack reaches 5, all effects are consumed to grant you 12 of all three attributes for 12 sec.\nSell Price:" }
entries[151956] = { ["name"] = "Garothi Feedback Conduit", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+5 Intellect\nEquip: Your healing effects have a chance to increase your Haste by 5 for 8 sec, stacking up to 5 times. This is more likely to occur when you heal allies who are at low health.\nSell Price:" }
entries[151957] = { ["name"] = "Ishkar's Felshield Emitter", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Versatility\nUse: Place a Felshield on an ally, absorbing [ 227 * (1 + Versatility)] damage for 9 sec. When the shield is consumed or expires, it explodes dealing 50 % of the absorbed damage as Fire split amongst all enemies within 8 yds. (1 Min Cooldown)\nSell Price:" }
entries[151958] = { ["name"] = "Tarratus Keystone", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+5 Intellect\nUse: Open a portal at an ally's location that releases brilliant light, restoring 227 health split amongst injured allies within 20 yds. (1 Min, 30 Sec Cooldown)\n\"A prison world for rebellious demons, the radiance of Tarratus' sun is breathtaking to behold.\"\nSell Price:" }
entries[151959] = { ["name"] = "7.3 Raid - Antorus - Boss 11 - Trinket Healer WS", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 10,651 Critical Strike\nSell Price:" }
entries[151960] = { ["name"] = "Carafe of Searing Light", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+5 Intellect\nUse: Sear an enemy with holy light, inflicting 98 Holy damage over 18 sec. Restores 8 mana each time damage is dealt. (1 Min Cooldown)\nSell Price:" }
entries[151961] = { ["name"] = "Legionsteel Flywheel", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Critical Strike\nSell Price:" }
entries[151962] = { ["name"] = "Prototype Personnel Decimator", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Haste\nEquip: Your ranged attacks and spells have a chance to launch a Homing Missile if your target is at least 10 yds away, dealing up to 28 Fire damage to all enemies within 20 yds. Targets closer to the impact take more damage.\nSell Price:" }
entries[151963] = { ["name"] = "Forgefiend's Fabricator", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Mastery\nEquip: Your melee and ranged attacks have a chance to plant Fire Mines at the enemy's feet. Fire Mines detonate after 15 sec, inflicting 15 Fire damage to all enemies within 12 yds.\nUse: Detonate all Fire Mines. (30 Sec Cooldown)\nSell Price:" }
entries[151964] = { ["name"] = "Seeping Scourgewing", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Versatility\nEquip: Your melee attacks have a chance to deal 39 Shadow damage to the target. If there are no other enemies within 8 yds of them, this deals an additional 17 damage.\nSell Price:" }
entries[151965] = { ["name"] = "Vulcanarcore Pendant", ["text"] = "Binds when picked up\nNeck\n+4 Stamina\n+ 6 Critical Strike\n+ 8 Versatility\nSell Price:" }
