entries[151967] = { ["name"] = "Electrostatic Lasso", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+54,289 [Agility or Strength]\nUse: Your attacks and abilities have a chance to electrify the target, dealing 498242 Nature damage every 0.5 sec for 3 sec.\nSell Price:" }
entries[151968] = { ["name"] = "Shadow-Singed Fang", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\nEquip: Your melee and ranged abilities have a chance to increase your Strength or Agility by 9 for 12 sec.\nEquip: Your autoattacks have a chance to increase your Critical Strike by 14 for 12 sec.\nSell Price:" }
entries[151969] = { ["name"] = "Terminus Signaling Beacon", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Mastery\nUse: Call a Legion ship to bombard the target's location for 9 sec, dealing 30 Fire damage to all targets within 12 yds, including the ship. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[151970] = { ["name"] = "Vitality Resonator", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Versatility\nUse: Redirect the life force of an enemy, increasing your Intellect by up to 18 for 15 sec. This grants more Intellect when used against targets at high health. (1 Min Cooldown)\nSell Price:" }
entries[151971] = { ["name"] = "Sheath of Asara", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+5 Intellect\nEquip: Your damaging spells have a chance to conjure 6 Shadow Blades. After 2 sec, the swords begin launching forward, each dealing 16 Shadow damage to the first enemy in their path and increasing damage taken from your subsequent Shadow Blades by 10% for 3 sec, up to 50%. (6s cooldown)\nSell Price:" }
entries[151972] = { ["name"] = "Sullied Seal of the Pantheon", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+5 Stamina\n+ 7 Versatility\n+ 10 Mastery\nSell Price:" }
