entries[151975] = { ["name"] = "Apocalypse Drive", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Haste\nUse: Reduce the damage of the next 10 melee attacks against you by up to 38 each. Lasts up to 20 sec.\n\nSuffering melee attacks reduces the cooldown of this ability by 1 sec. (2 Min Cooldown)\nSell Price:" }
entries[151976] = { ["name"] = "Riftworld Codex", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Critical Strike\nEquip: Taking damage has a chance to open a portal to another world, either healing you, providing an absorption shield, or empowering you with shadowflame magic. (4s cooldown)\nSell Price:" }
entries[151977] = { ["name"] = "Diima's Glacial Aegis", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+5 [Agility or Strength]\nUse: Increase your Armor by 2 for 12 sec, and inflict 65 Frost damage to enemies within 12 yds and reduce their movement speed by 70% for 12 sec. (1 Min Cooldown)\nSell Price:" }
entries[151978] = { ["name"] = "Smoldering Titanguard", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 7 Mastery\nUse: Channel a Bulwark of Flame that absorbs 512 damage for 3 sec. When the Bulwark expires you unleash 4 Waves of Flame, dealing 72 Fire damage to all enemies in their path.\n\nYou cannot move or use abilities during Bulwark of Flame. (2 Min Cooldown)\nSell Price:" }
